{
  "title": "이동 경로의 전환과 체류 및 회귀 기록",
  "cards": [
    {
      "stamp_id": "stamp:how:12081edea0846f8b",
      "title": "경로의 우회전과 직선 주행",
      "text": "우회전 기동을 중심으로 전후의 직선 주행 구간이 연결되어 이동 경로가 형성되었습니다."
    },
    {
      "stamp_id": "stamp:how:7a66b966562f7523",
      "title": "특정 지점에서의 체류",
      "text": "직선 주행 경로상에서 80초 동안 관찰된 체류 지점이 기록되었습니다."
    },
    {
      "stamp_id": "stamp:how:beaed9b87b263c05",
      "title": "경로 회귀와 방향 전환",
      "text": "이전 경로를 따라 79.58미터만큼 회귀하며 방향을 반대로 전환하고 새로운 직선 주행을 시작했습니다."
    }
  ]
}
